+                ? 0
+                : MachineLearning.NATIVE_EXECUTABLE_CODE_OVERHEAD.getBytes());
+            long nodeFreeMemory = assignmentPlan.getRemainingNodeMemory(node.getId()) + (isPerNodeOverheadAccountedFor
+                ? 0
+                : MachineLearning.NATIVE_EXECUTABLE_CODE_OVERHEAD.getBytes());
